def init_state() -> None:
    default = PRESETS["Published binary NiTi example"]
    assert default is not None
    for key, value in {
        "a_b2": default.a_b2,
        "a_b19p": default.a_b19p,
        "b_b19p": default.b_b19p,
        "c_b19p": default.c_b19p,
        "beta_deg": default.beta_deg,
    }.items():
        st.session_state.setdefault(key, value)


def load_preset(name: str) -> None:
    p = PRESETS[name]
    if p is None:
        return
    st.session_state.a_b2 = p.a_b2
    st.session_state.a_b19p = p.a_b19p
    st.session_state.b_b19p = p.b_b19p
    st.session_state.c_b19p = p.c_b19p
    st.session_state.beta_deg = p.beta_deg


def number_with_unit(label: str, key: str, unit: str, help_text: str, min_value: float, max_value: float, step: float, fmt: str) -> None:
    st.markdown(f"**{label}**")
    c1, c2 = st.columns([11, 1], vertical_alignment="bottom")
    with c1:
        st.number_input(
            label,
            key=key,
            min_value=min_value,
            max_value=max_value,
            step=step,
            format=fmt,
            help=help_text,
            label_visibility="collapsed",
        )
    with c2:
        st.markdown(f'<div class="unit-cell">{unit}</div>', unsafe_allow_html=True)


def axis_label(axis: np.ndarray) -> str:
    v = np.asarray(axis, float)
    nz = np.abs(v[np.abs(v) > 1e-8])
    if len(nz):
        w = np.rint(v / np.min(nz)).astype(int)
        for x in w:
            if x != 0:
                if x < 0:
                    w *= -1
                break
        return "[" + " ".join(str(int(x)) for x in w) + "]"
    return "[0 0 0]"


def domain_spec_label(spec: CofactorDomainSpec) -> str:
    if spec.partner_axis is None:
        return f"{spec.domain_type} · ê={axis_label(spec.axis)}"
    return f"{spec.domain_type} · ê={axis_label(spec.axis)} · partner={axis_label(spec.partner_axis)}"


def plane_text(p: np.ndarray) -> str:
    return "(" + ", ".join(f"{x:.5f}" for x in p) + ")"


def pct(x: float) -> str:
    return f"{100*x:.1f}%"


