    st.header("Complete twin explorer")
    st.markdown("The built-in cubic parent symmetry group contains 48 operations. The correspondence intersection subgroup has 4 operations, and the parent group is partitioned into **7 double-coset classes** to expose equivalent variant-pair relationships without hiding redundancy.")

    dcs = double_cosets()
    dcrows = [{
        "Class": d.label,
        "size": len(d.matrices),
        "polar": d.polar,
        "contains identity": d.contains_identity,
        "mirrors": d.n_mirrors,
        "180° rotations": d.n_twofold_rotations,
    } for d in dcs]
    st.dataframe(pd.DataFrame(dcrows), use_container_width=True, hide_index=True)

    entries = full_twin_explorer(ma, mm)
    cpairs = compound_twin_pairs(entries)
    compound_indices = {idx for pair in cpairs for idx in pair}
    partner = {}
    for i, j in cpairs:
        partner[i] = entries[j].parent_element
        partner[j] = entries[i].parent_element
    twin_rows = []
    for idx, e in enumerate(entries):
        twin_rows.append({
            "Double coset": e.double_coset,
            "Twin type": e.twin.twin_type,
            "Compound twin": idx in compound_indices,
            "Equivalent Type-I/II partner": partner.get(idx, ""),
            "Parent symmetry": e.parent_element,
            "Twin shear amplitude": e.twin.shear_amplitude,
            "Twin shear vector": format_vector(e.twin.twin_shear_vector),
            "Twin plane normal": format_vector(e.twin.twin_plane_normal),
        })
    st.subheader("All two-fold-generated transformation-twin candidates")
    st.caption("Compound twins are detected when Type-I and Type-II descriptions in the same intercorrespondence class produce the same shear plane and shear direction up to sign/scaling.")
    st.dataframe(pd.DataFrame(twin_rows), use_container_width=True, hide_index=True)

    st.subheader("Metric shear/shear matching")
    if not deg.habit_planes:
        st.info("CMC does not currently provide an exact A/M habit plane, so ε is not evaluated. Load the C1-compatible or rounded supercompatible example to inspect matching.")
    else:
        matches = []
        for e in entries:
            for p in deg.habit_planes:
                m = shear_match(p, smc, e.twin, ma)
                matches.append({
                    "Double coset": e.double_coset,
                    "Twin type": e.twin.twin_type,
                    "Parent symmetry": e.parent_element,
                    "Habit plane": plane_text(p),
                    "ε": m.epsilon,
                    "shear-direction angle (°)": m.angle_deg,
                    "A/M shear d_A": format_vector(m.shear_direction),
                })
        mdf = pd.DataFrame(matches).sort_values("ε")
        st.dataframe(mdf, use_container_width=True, hide_index=True)
        best = mdf.iloc[0]
        st.metric("Best ε across the full explorer", f"{best['ε']:.8f}", help="ε=0 is exact metric shear/shear matching.")


